const localeKey = "miguel-portfolio-locale";
const themeKey = "miguel-portfolio-theme";
const rtlLocales = new Set(["ar"]);
const root = document.documentElement;
const languageSelect = document.getElementById("language-select");
const themeToggle = document.getElementById("theme-toggle");
const themeIcon = document.getElementById("theme-icon");
const themeMeta = document.querySelector('meta[name="theme-color"]');

function readStorage(key) {
  try { return localStorage.getItem(key); } catch { return null; }
}

function writeStorage(key, value) {
  try { localStorage.setItem(key, value); } catch { /* Storage may be disabled. */ }
}

function setLocalizedText(element, value) {
  const textNode = Array.from(element.childNodes).find((node) => node.nodeType === Node.TEXT_NODE && node.textContent.trim());
  if (textNode) {
    const trailingSpace = /\s$/.test(textNode.textContent) ? " " : "";
    textNode.textContent = `${value}${trailingSpace}`;
  } else {
    element.textContent = value;
  }
}

function applyLocale(locale) {
  const selected = translations[locale] ? locale : "en";
  const dictionary = translations[selected];
  root.lang = selected === "pt-BR" ? "pt-BR" : selected;
  root.dir = rtlLocales.has(selected) ? "rtl" : "ltr";
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const value = dictionary[element.dataset.i18n] || translations.en[element.dataset.i18n];
    if (value) setLocalizedText(element, value);
  });
  const title = dictionary["meta.title"] || translations.en["meta.title"];
  const description = dictionary["meta.description"] || translations.en["meta.description"];
  document.title = title;
  document.querySelector('meta[name="description"]').setAttribute("content", description);
  document.querySelector('meta[property="og:title"]').setAttribute("content", title);
  document.querySelector('meta[property="og:description"]').setAttribute("content", description);
  languageSelect.value = selected;
  writeStorage(localeKey, selected);
}

function preferredTheme() {
  const saved = readStorage(themeKey);
  if (saved === "light" || saved === "dark") return saved;
  return window.matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
}

function applyTheme(theme, persist = true) {
  const selected = theme === "light" ? "light" : "dark";
  root.dataset.theme = selected;
  themeMeta?.setAttribute("content", selected === "dark" ? "#0b1118" : "#f7f8f4");
  themeIcon.innerHTML = selected === "dark"
    ? '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"></circle><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"></path></svg>'
    : '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 15.2A8.5 8.5 0 0 1 8.8 3.5 8.5 8.5 0 1 0 20.5 15.2Z"></path></svg>';
  const dictionary = translations[root.lang] || translations.en;
  const key = selected === "dark" ? "controls.switchToLight" : "controls.switchToDark";
  themeToggle.setAttribute("aria-label", dictionary[key] || translations.en[key]);
  themeToggle.setAttribute("title", dictionary[key] || translations.en[key]);
  if (persist) writeStorage(themeKey, selected);
}

languageSelect.addEventListener("change", (event) => {
  applyLocale(event.target.value);
  applyTheme(root.dataset.theme, false);
});
themeToggle.addEventListener("click", () => applyTheme(root.dataset.theme === "dark" ? "light" : "dark"));

applyLocale(readStorage(localeKey) || "en");
applyTheme(preferredTheme(), false);

const sectionLinks = [...document.querySelectorAll('nav a[href^="#"]')];
const sectionTargets = sectionLinks
  .map((link) => document.querySelector(link.getAttribute("href")))
  .filter(Boolean);

function updateActiveSection(sectionId) {
  sectionLinks.forEach((link) => {
    const isActive = link.getAttribute("href") === `#${sectionId}`;
    if (isActive) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  });
}

function syncActiveSection() {
  const marker = window.innerHeight * .34;
  const current = sectionTargets.reduce((selected, section) => {
    return section.getBoundingClientRect().top <= marker ? section : selected;
  }, null);
  if (current) updateActiveSection(current.id);
}

window.addEventListener("scroll", syncActiveSection, { passive: true });
window.addEventListener("resize", syncActiveSection);
syncActiveSection();
